  "Termine l’exercice ou la partie en cours avant de terminer ce bloc. Tu peux revenir au programme et le reprendre plus tard.": "أنهي التمرينات الحالية أو لعبة الشطرنج قبل الانتهاء من هذه الكتلة. يمكنك العودة إلى البرنامج واستئنافه لاحقاً",
