  "Ce brouillon a changé sur un autre appareil. Conserve ton brouillon local avant de choisir la version à reprendre.": "هذا المسودة تغيرت على جهاز آخر. حافظ على مسودتك المحلية قبل اختيار النسخة التي ستستأنفها",
