  "Brouillon repris. La partie dans la base reste inchangée jusqu’à Sauvegarder.": "تم استئناف المسودة قاعدة بيانات لعبة الشطرنج تبقى دون تغيير حتى تضغط على حفظ.",
  "Appliquer au brouillon": "تطبيق المسودة",
  "La partie reste inchangée dans la base jusqu’à Sauvegarder.": "قاعدة بيانات لعبة الشطرنج تبقى دون تغيير حتى تضغط على حفظ.",
  "Annotation appliquée au brouillon. Sauvegarde la partie pour la conserver dans la base.": "الملاحظة المطبقة على المسودة حفظ لعبة الشطرنج للحفاظ عليها في قاعدة البيانات.",
  "Informations PGN appliquées au brouillon. Sauvegarde la partie pour les conserver dans la base.": "PGN المعلومات المطبقة على المشروع. حفظ لعبة الشطرنج للحفاظ عليها في قاعدة البيانات.",
  "Reprendre la séance en cours. Les modifications restent en brouillon tant que tu ne sauvegardes pas.": "استئناف الجلسة الحالية. التغييرات تبقى في المسودة حتى تدخر.",
  "Préparation des statistiques exactes de cette position…": "إعداد الإحصاءات الدقيقة لهذا الموقف...",
  "Préparation des statistiques exactes de cette position. Elles apparaîtront automatiquement dès que le calcul sera terminé.": "إعداد الإحصاءات الدقيقة لهذا الموقف ستظهر تلقائيًا بمجرد اكتمال الحساب.",
  "Ce calcul a dépassé le délai disponible. Réessaie dans un instant ou choisis une position plus avancée.": "هذا الحساب تجاوز الوقت المتاح. حاول مرة أخرى بعد قليل أو اختر مكانا لاحقا",
  "Statistiques exactes des parties importées. Les parties rejetées pendant l’importation sont exclues.": "إحصائيات دقيقة لعبة الشطرنج المستوردة يتم استبعاد ألعاب الشطرنج التي رفضت أثناء الاستيراد.",
  "Les résultats apparaîtront automatiquement dès qu’ils seront prêts.": "ستظهر النتائج تلقائياً عندما تكون جاهزة.",
  "La préparation continue sur le serveur. Clique sur Actualiser pour vérifier le résultat.": "يستمر التحضير على الخادم انقر فوق Refresh للتحقق من النتيجة.",
  "Actualisation interrompue. Clique sur Actualiser pour réessayer.": "التجديد مقاطعة. اضغط على Refresh لمحاولة مرة أخرى.",
  "Cette partie est trop longue pour être exportée depuis cet éditeur. Utilise l’export de la base.": "هذه اللعبة شطرنجية طويلة جدا لتصدير من هذا المحرر. استخدم مصدر قاعدة البيانات",
  "La position de départ de cette variante est introuvable.": "لم يتم العثور على موقع البداية لهذا التغير.",
