  "· filtres actifs": "المصفحات · نشطة",
  "· toutes les parties": "· جميع ألعاب الشطرنج",
  "Elo minimum · chaque joueur": "الحد الأدنى Elo · لكل لاعب",
  "Elo maximum · chaque joueur": "أقصى Elo · لكل لاعب",
  "Sans minimum": "لا الحد الأدنى",
  "Cadences du PGN": "PGN التحكم في الوقت",
  "Sans maximum": "لا يوجد حد أقصى",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "لا خيار = جميع التحكمات في الوقت، بما في ذلك غير المعروف.",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo يأتي من PGN ويجب أن يكون ضمن نطاق كلا اللاعبين. لا يتم استبعاد ألعاب الشطرنج بدون Elo عند تحديد الحد. ضوابط الوقت المفقودة أو غير المعترف بها PGN هي \"غير معروفة\". يتم استبعاد ألعاب الشطرنج هذه عندما يتم اختيار التحكم في الوقت، ما لم يتم اختيار \"غير معروف\".",
  ": indique un nombre valide pour la borne Elo.": ": إدراج رقم صالح للخط Elo.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": أدخل رقمًا كاملًا Elo من 0 إلى 4000، أو اترك الرقم المرتبط فارغًا.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": الحد الأدنى Elo لا يمكن أن يتجاوز الحد الأقصى Elo.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "إنشاء قاعدة بيانات واستيراد PGN ألعاب الشطرنج في المكتبة.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess لا يحتوي على Elo أو مرشحات مراقبة الوقت. لتصفية مجموعة رئيسية، اختر قاعدة بيانات مستوردة مثل قاعدة بيانات ميغا.",
  "Source principale": "المصدر الرئيسي",
  "Mes bases PGN": "قواعد بياناتي PGN",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "يتم احتساب حركات الشطرنج الرئيسية فقط. التباينات في التحليل لا تتضخم الإحصاءات.",
  "Référence dans chaque ligne": "الإشارة في كل سطر",
  "Comparer avec": "مقارنة",
  "Mes bases de référence": "قواعد بياناتي المرجعية",
  "Aucune référence": "لا يوجد إشارة",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "هذه المرشحات مستقلة عن قاعدة البيانات الرئيسية. تظهر النسبة المئوية تردد حركة الشطرنج في هذا الموقف في المرجع المختار.",
  "Probabilité de rencontre": "إحتمالية التواجد",
  "Afficher la probabilité de la ligne": "أظهر احتمال الخط",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "اختر جانبك مباشرة في المستكشف فقط إجابات المُعارضين هي التي تعتبر، تحركات الشطرنج الخاصة بك هي المفترضة. هذه التقديرات تتبع التغيرات المعروضة ومصفحات قاعدة البيانات المختارة. بالنسبة لـ PGN تبدأ من الرسم البياني، فإنه يعتمد على هذا الموقف البدائي.",
  "Mode d’analyse": "وضع التحليل",
  "Rapide (~250 ms par coup)": "سريع (~ 250 ms لكل خطوة شطرنجية)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "عمق أعلى يحسن التحليل و يستغرق وقتا أطول من 8 إلى 30، مع حد 10 ثوانٍ لكل خطوة شطرنج. إذا لم يتم الوصول إلى الهدف، ≈ تعبر النتيجة؛ تحلق لرؤية عمقها الفعلي.",
  "Chargement de la connexion…": "اتصالات الشحن",
  "Connexion indisponible.": "الاتصال غير متوفر",
  "Jeton fourni par le serveur.": "رمز تم توفيره من قبل الخادم.",
  "Configuration du serveur à corriger.": "تكوين الخادم يحتاج إلى تصحيح.",
  "Jeton enregistré.": "تم حفظ الرمز",
  "Aucun jeton enregistré.": "لا توجد رموز محفوظة",
  "Cette connexion est gérée dans la configuration du serveur.": "يتم إدارة هذا الاتصال في تكوين الخادم.",
  "Crée un jeton sans cocher de permissions, puis colle-le ici. Il reste sur ton serveur.": "قم بإنشاء رمز بدون اختيار الإذن، ثم ضعه هنا. إنه يبقى على خادمك",
  "Créer un jeton Lichess ↗": "إنشاء رمز Lichess ↗",
  "Jeton personnel Lichess": "رمز شخصي Lichess",
