  "Aucune carte disponible pour ce bloc. Ajuste les révisions de la base ou choisis une autre activité.": "لا توجد بطاقات متاحة لهذا الحي تعديل مراجعات قاعدة البيانات أو اختر نشاط آخر.",
  "Cette ressource de lecture est indisponible. Vérifie les réglages de la base.": "هذا المصدر للقراءة غير متوفر. تحقق من إعدادات قاعدة البيانات",
