  "Durées enregistrées pour les activités sélectionnées": "المدد المسجّلة للأنشطة المحدّدة",
  "Stockfish sert à l’analyse et au jeu classique; Maia reproduit un jeu humain. Les bases de référence et de puzzles restent facultatives.": "يوفّر Stockfish التحليل واللعب التقليدي؛ ويحاكي Maia اللعب البشري. قواعد بيانات المراجع والألغاز اختيارية.",
  "Quand ChessGym est ouvert, les versions compatibles des moteurs et les bases installées compatibles sont vérifiées puis actualisées. Les éditions Lumbra se téléchargent séparément sur leur site. Les téléchargements peuvent être volumineux.": "أثناء تشغيل ChessGym، تُفحص الإصدارات المتوافقة من المحركات وقواعد البيانات المثبّتة وتُحدَّث. تُنزَّل إصدارات Lumbra بشكل منفصل من موقعها. قد تكون التنزيلات كبيرة.",
  "Licence : {license}": "الترخيص: {license}",
  "Conditions de licence": "شروط الترخيص",
  "Par Michael Jansen. Usage non commercial avec attribution; une licence distincte est nécessaire pour un usage commercial.": "من إعداد Michael Jansen. للاستخدام غير التجاري مع ذكر المصدر؛ يتطلّب الاستخدام التجاري ترخيصًا منفصلًا.",
  "Télécharge cette édition sur le site Lumbra, accepte sa licence, puis indique le fichier .7z ou .pgn présent sur le PC ou serveur de ChessGym.": "نزّل هذا الإصدار من موقع Lumbra، واقبل ترخيصه، ثم أدخل مسار ملف .7z أو .pgn الموجود على الحاسوب أو الخادم الذي يشغّل ChessGym.",
  "Télécharger sur Lumbra": "التنزيل من Lumbra",
  "Chemin du fichier téléchargé sur le serveur": "مسار الملف المنزّل على الخادم",
  "Ex. C:\\Téléchargements\\Lumbra.7z": "مثال: C:\\Downloads\\Lumbra.7z",
  "Utiliser comme référence de maîtres": "استخدامها قاعدةً مرجعية لمباريات الأساتذة",
  "Importer la base téléchargée": "استيراد قاعدة البيانات المنزّلة",
  "Les nouvelles éditions Lumbra se téléchargent sur leur site; les mises à jour automatiques ne les remplacent pas.": "نزّل إصدارات Lumbra الجديدة من موقعها؛ لا تستبدلها التحديثات التلقائية.",
  "Taille de l’archive : environ {size} Mo": "حجم الأرشيف: نحو {size} ميغابايت",
  "Indique le chemin du fichier Lumbra téléchargé.": "أدخل مسار ملف Lumbra المنزّل.",
  "Lumbra OTB Elite — maîtres 2400+": "Lumbra OTB Elite — أساتذة بتصنيف 2400 فأعلى",
  "Lumbra Gigabase OTB — complète": "Lumbra Gigabase OTB — كاملة",
  "Parties sur échiquier entre deux joueurs classés au moins 2400 Elo. Télécharge l’archive officielle, puis importe-la ici.": "مباريات على الرقعة بين لاعبين لا يقل تصنيف أيٍّ منهما عن 2400 إيلو. نزّل الأرشيف الرسمي ثم استورده هنا.",
  "Collection complète des parties sur échiquier. L’import et l’indexation peuvent prendre plusieurs heures et beaucoup d’espace disque.": "المجموعة الكاملة لمباريات الرقعة. قد يستغرق الاستيراد والفهرسة عدة ساعات ويتطلّب مساحة كبيرة على القرص.",
  "Gratuit avec attribution pour un usage non commercial. Une licence distincte est nécessaire pour un usage commercial.": "مجاني للاستخدام غير التجاري مع ذكر المصدر. يتطلّب الاستخدام التجاري ترخيصًا منفصلًا.",
