  "Base Lumbra disponible": "قاعدة بيانات Lumbra جاهزة",
  "7-Zip n’est pas détecté sur le serveur. Installe-le pour importer une archive .7z, ou fournis un PGN déjà extrait.": "لم يُعثر على 7-Zip على الخادم. ثبّته لاستيراد أرشيف .7z، أو قدّم ملف PGN مستخرجًا مسبقًا.",
  "Installe 7-Zip sur le serveur, ou décompresse l’archive et importe directement son fichier PGN.": "ثبّت 7-Zip على الخادم، أو استخرج الأرشيف واستورد ملف PGN مباشرةً.",
  "Bonus dans 1 coup : +{seconds} s": "مكافأة بعد نقلة واحدة: +{seconds} ث",
  "Seule la résolution sans erreur compte pour le classement. La reconstruction est une statistique secondaire, sans effet sur la cote. Une erreur, une révélation ou un abandon avant la fin de la solution peut faire baisser la cote.": "الحل الخالي من الأخطاء وحده يؤثّر في التصنيف. إعادة بناء الوضعية إحصائية ثانوية لا تؤثّر في التصنيف. قد يؤدّي الخطأ أو كشف الحل أو الانسحاب قبل إكماله إلى انخفاض التصنيف.",
  "Classé : seule la résolution sans erreur compte. La reconstruction ne change pas la cote.": "مصنّف: يُحتسب الحل الخالي من الأخطاء فقط. إعادة بناء الوضعية لا تغيّر التصنيف.",
  "Solution sans erreur.": "حل دون أخطاء.",
