  "Les parties sélectionnées seront supprimées de cette base de référence. Le fichier PGN original est conservé. Cette action ne peut pas être annulée.": "ستُحذف المباريات المحدّدة من قاعدة البيانات المرجعية هذه. سيُحتفظ بملف PGN الأصلي. لا يمكن التراجع عن هذا الإجراء.",
  "Les parties seront copiées dans la base choisie, puis supprimées de cette base de référence. Le fichier PGN original est conservé.": "ستُنسخ المباريات إلى قاعدة البيانات المختارة، ثم تُحذف من قاعدة البيانات المرجعية هذه. سيُحتفظ بملف PGN الأصلي.",
  "Une copie indépendante sera créée avec tous les coups, variantes et commentaires.": "ستُنشأ نسخة مستقلة تتضمّن كل النقلات والتفرّعات والتعليقات.",
