  "Sélectionne des parties pour les dupliquer, les déplacer ou les supprimer. Pour les annoter ou les réviser, duplique-les dans une base personnelle. L’explorer et la recherche de positions utilisent la ligne principale des parties de référence.": "حدّد مباريات لنسخها أو نقلها أو حذفها. لإضافة تعليقات إليها أو مراجعتها، انسخها إلى قاعدة بيانات شخصية. يستخدم المستكشف والبحث عن الوضعيات الخط الرئيسي للمباريات المرجعية.",
  "Reprends la partie pour continuer.": "استأنف المباراة للمتابعة.",
