  "Un lancement attend une confirmation. Réessaie le même choix pour retrouver tes cartes.": "بدء جلسة قيد انتظار التأكيد. أعد اختيار الخيار نفسه لاستعادة بطاقاتك.",
  "Réviser / Apprendre": "مراجعة / تعلّم",
  "Cartes à travailler": "بطاقات للدراسة",
  "Les erreurs personnelles et puzzles échoués proviennent des exercices déjà présents dans tes bases actives. Les révisions dues passent avant les nouvelles cartes.": "تأتي الأخطاء الشخصية والألغاز غير المحلولة من التمارين الموجودة بالفعل في قواعد بياناتك النشطة. تُقدَّم المراجعات المستحقة على البطاقات الجديدة.",
