  "Les révisions dues passent avant les nouvelles cartes. Le volume dépend de l’objectif du bloc.": "تُقدَّم المراجعات المستحقة على البطاقات الجديدة. يحدّد هدف الوحدة حجم العمل.",
  "Les révisions dues passent avant les nouvelles cartes.": "تُقدَّم المراجعات المستحقة على البطاقات الجديدة.",
