  "Le calendrier et les séries de jours utilisent la même journée d’étude.": "يستخدم التقويم وسلاسل أيام الدراسة تعريف يوم الدراسة نفسه.",
  "Ces objectifs proposent une pause sans modifier les échéances. Tu peux les adapter au lancement.": "تقترح هذه الأهداف استراحة دون تغيير مواعيد المراجعة. يمكنك تعديلها عند البدء.",
  "Choisis les bases à mettre à jour avec les valeurs globales Manqué, Difficile, Bien et Facile. Les échéances et l’historique restent conservés.": "اختر قواعد البيانات التي تريد تحديثها بالقيم العامة للخيارات «أعد المحاولة» و«صعب» و«جيد» و«سهل». تُحفَظ المواعيد والسجل.",
